import type { Config } from '../config/schema.ts'
import { PAGE_DIRS } from './layout.ts'

/**
 * Generates the store's schema document.
 *
 * This is the portability play, and it is worth more than it costs: an agent
 * pointed at the store with NO MCP server, no CLI, and no knowledge of hoppr
 * can read this file and work the wiki correctly. The MCP server and hybrid
 * search are accelerants on top of a store that already works as plain files.
 *
 * Regenerated by `hoppr schema sync` whenever config changes.
 */
export function renderClaudeMd(cfg: Config): string {
  const userFields = Object.entries(cfg.schema)
  const tableNames = Object.keys(cfg.tables).filter((t) => t !== 'tags')

  return `# hoppr store

This directory is a **hoppr** store: a git-tracked knowledge base that an agent
maintains. It follows the LLM-wiki pattern: source material remains under its
owner's control, and an agent compiles it into a linked markdown wiki.

<!-- Generated by \`hoppr schema sync\`. Edits are overwritten. Put durable
     instructions in curated/prompts/ instead — those are yours. -->

## The one rule

\`\`\`
source folder/  externally owned files   NEVER modify or delete through hoppr
raw/            durable captures         intake-managed; curator must not edit
curated/        agent-written output     regenerable — safe to change or rebuild
.index/         search index             disposable, gitignored
\`\`\`

Everything in \`curated/\` can be regenerated from the configured source. If you
are unsure whether the curator may write to a path, the answer is yes for
\`curated/\` and no for the source folder or \`raw/\`.

## Layout

\`\`\`
raw/<YYYY>/<MM>/<DD>/<ULID>.<ext>        durable captured content (copy mode)
raw/<YYYY>/<MM>/<DD>/<ULID>.meta.json    provenance sidecar

curated/wiki/index.md                    catalog — READ THIS FIRST to navigate
curated/wiki/log.md                      append-only record of every operation
curated/wiki/overview.md                 narrative front door
curated/wiki/sources/<slug>.md           one page per raw capture
curated/wiki/concepts/<slug>.md          accumulates across sources
curated/wiki/entities/<slug>.md          people, tools, repos, projects
curated/wiki/comparisons/<slug>.md       A-vs-B pages
curated/wiki/digests/<period>.md         time-boxed rollups

curated/tables/<name>.table.toml         extraction schema (hand-editable)
curated/tables/<name>.jsonl              extracted rows
curated/tables/tags.yaml                 the tag vocabulary

curated/skills/<slug>/SKILL.md           procedures distilled from past sessions
curated/prompts/*.md                     the prompts driving curation — editable
curated/outputs/lint-<date>.md           lint reports
\`\`\`

## Page frontmatter

Every wiki page carries YAML frontmatter:

\`\`\`yaml
---
title: Human-readable title
type: ${Object.keys(PAGE_DIRS).join(' | ')}
sources:                       # always relative paths into raw/
  - raw/2026/08/17/01JXQ7K4.jsonl
related:                       # [[wikilinks]] to other pages
  - "[[rrf-fusion]]"
created: 2026-08-17
updated: 2026-08-18
confidence: high               # high | medium | low
tags: [search, ranking]
project: hoppr${
    userFields.length
      ? `\n${userFields
          .map(
            ([name, f]) =>
              `${name}: ${f.type === 'enum' ? (f.values?.[0] ?? '') : `<${f.type}>`}${
                f.description ? `   # ${f.description}` : ''
              }`,
          )
          .join('\n')}`
      : ''
  }
hoppr:                         # machine-owned. Everything outside is the human's.
  id: 01JXQ9R7
  raw_ids: [01JXQ7K4M8ZT3W9V2H]
  pinned: false                # true => a human edited this; leave the prose alone
---
\`\`\`

**\`confidence\` is not decoration.** It damps search ranking, drives the lint
pass, and lets you write something useful without overclaiming. Use \`low\`
freely rather than omitting a page.

**\`pinned: true\`** means a human edited the page. You may still add evidence to
\`sources\`, but do not rewrite the prose.

## Naming and linking

- Filenames are **kebab-case** matching the concept: \`attention-mechanism.md\`.
- Internal references use **\`[[wikilinks]]\`** by slug: \`[[attention-mechanism]]\`.
- Source references **always link back to a \`raw/\` path**, never to a summary.
- Never link two pages of the same type without a named relation.

Link routes:

| From | To | Relation |
|---|---|---|
| source | \`raw/\` path | derived-from (mandatory) |
| source | concept, entity | about, mentions |
| concept | source | supported-by |
| comparison | 2+ concepts/entities | compares |
| digest | source, concept | rollup |

## Workflows

### Ingest
1. Read the new capture under \`raw/\`.
2. Create \`curated/wiki/sources/<slug>.md\` summarizing it, with \`sources:\`
   pointing at the raw path.
3. Update or create the relevant \`concepts/\` and \`entities/\` pages.
4. Reuse existing tags from \`curated/tables/tags.yaml\` wherever they fit;
   coin a new tag only when nothing existing covers the idea.
5. Append one line to \`curated/wiki/log.md\`.

### Query
1. Read \`curated/wiki/index.md\` to find relevant pages.
2. Read those pages and synthesize an answer, citing with \`[[wikilinks]]\`.
3. If the answer is novel and valuable, file it as a new \`concepts/\` or
   \`comparisons/\` page so the next question starts from it.

### Lint
Scan for: contradictions between pages, orphan pages with no incoming links,
concepts referenced but never created, stale claims superseded by newer
sources, and investigation gaps. Write findings to
\`curated/outputs/lint-<YYYY-MM-DD>.md\`.

## Tables

Structured data extracted from raw captures. Each \`<name>.table.toml\` declares
columns and a \`match\` selector; rows land in \`<name>.jsonl\` with a \`raw_id\`
so every cell traces back to its capture.${
    tableNames.length ? `\n\nDefined here: ${tableNames.map((t) => `\`${t}\``).join(', ')}.` : ''
  }

## Skills

\`curated/skills/<slug>/SKILL.md\` are procedures distilled from recurring
patterns in past agent sessions — including the failures, which are the point.
They are proposals until a human accepts them.

## Tooling (optional)

If hoppr is installed, these are faster than reading files directly:

\`\`\`
hoppr search "<question>"     hybrid keyword + semantic search over everything
hoppr catalog                 the wiki catalog
hoppr get <id>                one page with its sources and links
hoppr source <raw-id>         the original capture behind a page
hoppr ingest "<text>"         add something new
hoppr doctor                  check store health and configuration
\`\`\`

If an MCP server is configured, \`hoppr_search\`, \`hoppr_get\`, and
\`hoppr_source\` do the same thing. Neither is required: this store is plain
markdown and works without them.
`
}
